import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Setiap potongan memiliki rasio, baik Anda memilihnya maupun tidak. Rasio adalah bentuk persegi yang Anda simpan, dan rasio menentukan tempat gambar cocok dan tampilannya.</p>\n\n<p>Potongan kotak dan potongan lebar tidak bisa saling menggantikan. Satu cocok untuk foto profil, satu lagi cocok untuk spanduk, dan memakai yang salah berarti platform akan memotong ulang hasil kerja Anda.</p>\n\n<p>Artikel ini menjelaskan rasio umum, fungsi masing-masing, dan cara memilih. Artikel ini juga membahas rasio khusus, matematika di baliknya, dan kesalahan yang timbul karena mengabaikannya. Begitu Anda tahu rasio yang dibutuhkan, <a href=\"/id/potong-gambar/\">Pemotong Gambar</a> menyediakan preset 1:1, 4:3, dan 16:9 yang tinggal dipilih.</p>\n\n<h2 id=\"what-is-an-aspect-ratio\">Apa Itu Rasio Aspek?</h2>\n\n<p>Rasio aspek adalah hubungan antara lebar dan tinggi gambar, ditulis sebagai dua angka dengan titik dua di antaranya, misalnya 16:9.</p>\n\n<p>Angka itu menggambarkan perbandingan, bukan jumlah piksel. Gambar 16:9 bisa berukuran 1920 kali 1080 piksel atau 1280 kali 720 piksel, dan keduanya memiliki bentuk yang sama.</p>\n\n<p>Untuk menemukan rasio gambar apa pun, bagi lebar dengan tinggi. Foto selebar 1200 piksel dan setinggi 800 piksel memiliki rasio 1,5, yang sama dengan 3:2.</p>\n\n<p>Rasio penting karena tujuan menuntut bentuk. Platform yang menginginkan kotak akan memotong foto lebar, dan printer yang menginginkan 4:3 akan meregangkan atau memangkas apa pun selain itu.</p>\n\n<h2 id=\"ratio-1-1\">1:1 — Kotak</h2>\n\n<p>Rasio 1:1 berarti lebar dan tinggi sama, sehingga gambar menjadi kotak sempurna. Rasio ini paling umum di media sosial, dipakai foto profil dan postingan grid.</p>\n\n<p>Kotak terasa seimbang dan netral. Bentuk ini cocok untuk potret, foto produk, dan apa pun yang perlu berada di grid tanpa mengutamakan satu arah.</p>\n\n<p>Kelemahannya adalah sebagian besar platform menampilkan foto profil kotak sebagai lingkaran. Sudut kotak Anda terpotong, jadi jaga wajah tetap jauh di dalam bingkai.</p>\n\n<p>Saat memotong ke 1:1, pusatkan subjek dengan sedikit ruang di atas kepala. Wajah yang menyentuh tepi atas akan kehilangan rambut karena potongan lingkaran, dan subjek di sudut akan terpotong seluruhnya.</p>\n\n<h2 id=\"ratio-4-3\">4:3 — Bentuk Foto Klasik</h2>\n\n<p>Rasio 4:3 sedikit lebih lebar daripada tingginya. Bentuk ini adalah standar untuk layar televisi dan kamera digital awal, dan masih cocok untuk foto tradisional.</p>\n\n<p>Bentuk ini adalah pilihan bawaan yang bagus untuk dokumen dan halaman hasil scan, ketika konten lebih lebar dari kotak tetapi tidak selebar bingkai video. Bentuk ini juga tercetak dengan baik pada ukuran kertas standar.</p>\n\n<p>Banyak kamera ponsel masih menawarkan mode 4:3. Jika kamera Anda memotret dalam rasio ini, memotong ke 4:3 akan mempertahankan bingkai penuh dengan hampir tanpa ada yang dihapus.</p>\n\n<p>Gunakan 4:3 saat subjek butuh sedikit ruang horizontal tetapi gambar tidak seharusnya terasa panoramik. Foto grup, interior ruangan, atau dokumen semuanya cocok dengan bentuk ini.</p>\n\n<h2 id=\"ratio-3-2\">3:2 — Standar Kamera</h2>\n\n<p>Rasio 3:2 berasal dari kamera film 35mm, dan tetap menjadi bentuk bawaan untuk sebagian besar kamera DSLR dan mirrorless. Bentuk ini lebih lebar dari 4:3 tetapi lebih sempit dari 16:9.</p>\n\n<p>Bentuk ini cocok untuk lanskap dan fotografi jalanan, ketika lebar tambahan memberi pemandangan ruang bernapas tanpa mengubah gambar menjadi panorama.</p>\n\n<p>Ukuran cetak sering cocok dengan rasio ini. Cetakan 6 kali 4 inci persis 3:2, sehingga foto yang dipotong ke bentuk ini tercetak tanpa pemangkasan lebih lanjut.</p>\n\n<p>Jika kamera Anda memotret 3:2 dan Anda sering mencetak, jaga potongan Anda dalam rasio ini. Anda akan terhindar dari kejutan lab yang memotong tepi foto favorit Anda.</p>\n\n<h2 id=\"ratio-16-9\">16:9 — Layar Lebar</h2>\n\n<p>Rasio 16:9 adalah bentuk layar modern: televisi, monitor, dan layar ponsel dalam lanskap. Bentuk ini lebar, sinematik, dan dibuat untuk konten yang membentang di seluruh layar.</p>\n\n<p>Bentuk ini adalah pilihan tepat untuk thumbnail video, spanduk website, dan slide presentasi. Potongan 16:9 mengisi ruang tanpa meninggalkan bilah kosong di kedua sisi.</p>\n\n<p>Kelemahannya adalah ruang vertikal. Potongan 16:9 dari foto tinggi membuang banyak piksel atas dan bawah, sehingga subjek harus muat dengan nyaman dalam pita yang tipis.</p>\n\n<p>Jaga konten penting di tengah potongan 16:9. Platform sering memangkas sisi lagi untuk ponsel, sehingga apa pun yang dekat dengan tepi kiri atau kanan bisa hilang.</p>\n\n<h2 id=\"ratio-4-5-and-9-16\">4:5 dan 9:16 — Bentuk Vertikal</h2>\n\n<p>Rasio vertikal penting karena sebagian besar orang melihat konten di ponsel yang dipegang tegak. Potongan 4:5 adalah potret tinggi yang mengisi layar ponsel lebih banyak daripada kotak.</p>\n\n<p>Rasio 4:5 cocok untuk postingan potret di feed sosial. Gambar tampil lebih besar di ponsel daripada postingan kotak, sehingga gambar lebih menonjol tanpa memenuhi seluruh layar.</p>\n\n<p>Rasio 9:16 adalah satu layar ponsel penuh dalam orientasi potret. Bentuk ini adalah bentuk story, reel, dan video vertikal, dan mengisi layar dari tepi ke tepi.</p>\n\n<p>Potongan vertikal menuntut pembingkaian yang hati-hati. Lanskap lebar yang ditekan ke 9:16 kehilangan sebagian besar sisinya, sehingga rasio ini cocok untuk subjek tunggal, bukan pemandangan luas.</p>\n\n<h2 id=\"custom-ratios\">Rasio Khusus: Saat Tidak Ada Preset yang Cocok</h2>\n\n<p>Kadang tidak ada rasio standar yang cocok dengan tujuan Anda. Ukuran spanduk tertentu, sampul buku, atau formulir dengan dimensi piksel tetap semuanya butuh bentuk khusus.</p>\n\n<p>Mode bebas di tool pemotong memungkinkan Anda menyeret kotak ke bentuk apa pun. Tool menunjukkan dimensi hasil yang tepat, sehingga Anda bisa menyesuaikan ukuran yang diminta secara presisi.</p>\n\n<p>Rasio khusus juga berguna untuk memotong detail dari gambar yang lebih besar. Satu paragraf dari halaman, logo dari foto, atau wajah dari keramaian semuanya butuh bentuk yang tidak disediakan preset.</p>\n\n<p>Saat memakai rasio khusus, tuliskan dulu dimensi piksel yang Anda butuhkan. Potongan yang dibuat dengan perkiraan mudah salah, sedangkan potongan yang diperiksa dengan angka bersifat tepat.</p>\n\n<h2 id=\"ratio-vs-resolution\">Rasio vs Resolusi: Dua Hal Berbeda</h2>\n\n<p>Rasio menggambarkan bentuk, sedangkan resolusi menggambarkan ukuran dalam piksel. Dua gambar bisa berbagi rasio dan memiliki resolusi yang sangat berbeda, dan dua gambar bisa berbagi resolusi dan memiliki rasio berbeda.</p>\n\n<p>Potongan 1:1 berukuran 500 kali 500 piksel dan potongan 1:1 berukuran 2000 kali 2000 piksel memiliki bentuk yang sama, tetapi yang kedua membawa piksel enam belas kali lebih banyak.</p>\n\n<p>Hal ini penting karena platform yang butuh 1000 piksel akan meregangkan potongan 500 piksel dan membuatnya buram, meskipun bentuknya benar. Rasionya benar dan resolusinya salah.</p>\n\n<p>Selalu periksa kedua angka. Tool pemotong menunjukkan dimensi hasil, jadi pastikan bentuknya dengan rasio dan ukurannya dengan jumlah piksel sebelum mengunduh.</p>\n\n<h2 id=\"ratio-mistakes\">Kesalahan yang Timbul dari Rasio yang Salah</h2>\n\n<p>Kesalahan paling umum adalah memotong ke satu rasio lalu meregangkan hasilnya agar muat ke bentuk lain. Meregangkan mendistorsi wajah dan objek, dan kerusakannya langsung terlihat.</p>\n\n<p>Kesalahan lain adalah membiarkan platform memotong ulang gambar Anda. Foto kotak yang diunggah sebagai spanduk akan dipotong oleh platform, dan platform yang memilih apa yang dipotong, bukan Anda.</p>\n\n<p>Banyak orang juga lupa bahwa perubahan rasio membuang piksel. Memotong foto lebar menjadi kotak membuang sepertiga kiri dan kanan, yang mungkin berisi subjek.</p>\n\n<p>Perbaikannya adalah memilih rasio sebelum memotong, berdasarkan aturan tujuan. Pemeriksaan lima detik pada panduan ukuran platform mencegah ketiga kesalahan ini.</p>\n\n<h2 id=\"ratio-for-print\">Rasio untuk Cetak</h2>\n\n<p>Ukuran cetak memiliki rasionya sendiri, dan tidak selalu cocok dengan bentuk layar. Cetakan 6 kali 4 inci adalah 3:2, cetakan 10 kali 8 inci adalah 5:4, dan halaman A4 kira-kira 1,41:1.</p>\n\n<p>Sebelum mencetak, periksa rasio ukuran kertas dan potong agar cocok. Foto yang dipotong ke 16:9 akan meninggalkan bilah putih pada cetakan 4:3, atau kehilangan tepinya karena pangkasan printer.</p>\n\n<p>Cetak juga butuh resolusi, bukan hanya bentuk. Potongan kecil yang dicetak besar akan terlihat lembut, jadi pastikan jumlah pikselnya selain rasionya.</p>\n\n<p>Saat ragu, potong sedikit lebih besar dari ukuran cetak dan biarkan lab memangkas kelebihannya. Sedikit margin tambahan lebih aman daripada potongan yang bentuknya persis salah.</p>\n\n<h2 id=\"ratio-workflow\">Alur Kerja Memilih Rasio</h2>\n\n<p>Mulailah dengan mendaftar setiap tempat gambar akan tampil. Foto yang perlu menjadi foto profil, spanduk, dan cetakan butuh tiga potongan berbeda dari foto asli yang sama.</p>\n\n<p>Potong setiap versi secara terpisah dari file asli. Potongan dari potongan akan kehilangan kualitas, sedangkan potongan baru dari file asli tetap tajam.</p>\n\n<p>Beri nama setiap file berdasarkan tujuan dan rasionya, misalnya avatar-1x1.png atau spanduk-16x9.png. Nama yang jelas mencegah Anda mengunggah bentuk yang salah ke tempat yang salah.</p>\n\n<p>Simpan file asli. Tujuan mengubah aturan ukurannya, dan file asli yang disimpan memungkinkan Anda memotong ulang ke rasio baru tanpa berangkat dari salinan yang rusak.</p>\n\n<h2 id=\"ratio-cheat-sheet\">Contekan Rasio Cepat</h2>\n\n<p>Gunakan 1:1 untuk foto profil, postingan grid, dan apa pun yang ditampilkan dalam kotak atau lingkaran. Jaga subjek tetap di tengah dengan ruang di atas kepala.</p>\n\n<p>Gunakan 4:3 untuk foto tradisional, dokumen, dan cetakan pada kertas standar. Bentuk ini adalah bentuk foto serbaguna yang paling aman.</p>\n\n<p>Gunakan 3:2 untuk foto kamera yang Anda rencanakan untuk dicetak 6 kali 4 inci. Bentuk ini cocok dengan standar film dan sebagian besar hasil DSLR.</p>\n\n<p>Gunakan 16:9 untuk spanduk, thumbnail, dan slide. Jaga konten penting di tengah, jauh dari tepi yang dipangkas layar ponsel.</p>\n\n<h2 id=\"ratio-for-video-thumbnails\">Rasio untuk Thumbnail Video</h2>\n\n<p>Thumbnail video hampir selalu 16:9, karena thumbnail berada pada pemutar video yang memakai bentuk layar lebar. Thumbnail yang dipotong ke rasio lain akan diregangkan atau diberi bilah huruf oleh platform.</p>\n\n<p>Jaga wajah dan subjek utama tetap besar dalam potongan thumbnail. Thumbnail ditampilkan kecil di feed, sehingga subjek kecil menghilang dan subjek besar menarik perhatian.</p>\n\n<p>Sisakan ruang untuk teks jika Anda berencana menambah judul pada thumbnail. Potongan 16:9 dengan subjek di satu sisi dan ruang kosong di sisi lain memberi teks tempat untuk berada.</p>\n\n<p>Periksa thumbnail di ponsel sebelum menerbitkan. Potongan yang terlihat bagus di desktop bisa tidak terbaca di layar kecil, ketika thumbnail hanya selebar beberapa sentimeter.</p>\n\n<h2 id=\"ratio-for-ecommerce\">Rasio untuk E-commerce dan Listing Produk</h2>\n\n<p>Listing produk biasanya menuntut gambar kotak, karena grid kotak sejajar rapi dan terlihat profesional. Potongan 1:1 adalah pilihan paling aman untuk sebagian besar toko.</p>\n\n<p>Sebagian marketplace meminta rasio tertentu, misalnya 4:3 atau 3:2, dan mereka akan memotong gambar Anda jika tidak cocok. Periksa aturan listing sebelum memotong, bukan sesudahnya.</p>\n\n<p>Konsistensi lebih penting daripada kreativitas dalam grid produk. Potong setiap produk ke rasio yang sama dengan margin yang sama, agar katalog terlihat rapi dan bisa dipercaya.</p>\n\n<p>Untuk gambar utama pada halaman produk, rasio yang lebih lebar seperti 16:9 atau 3:2 bekerja lebih baik. Bentuk ini menampilkan produk dalam konteks, dengan ruang untuk latar gaya hidup di sekelilingnya.</p>\n\n<h2 id=\"ratio-and-composition\">Rasio dan Komposisi: Bagaimana Bentuk Mengubah Nuansa</h2>\n\n<p>Kotak terasa tenang dan seimbang, karena tidak ada arah yang mendominasi. Bentuk ini cocok untuk potret, still life, dan apa pun yang seharusnya terasa terpusat dan stabil.</p>\n\n<p>Rasio lebar terasa terbuka dan sinematik, karena mata bergerak melintasi bingkai. Bentuk ini cocok untuk lanskap, pemandangan kota, dan pemandangan apa pun yang lebarnya menjadi poin utama.</p>\n\n<p>Rasio tinggi terasa intim dan terfokus, karena mata bergerak naik turun dalam bingkai sempit. Bentuk ini cocok untuk subjek tunggal, seperti orang, bangunan, atau pohon.</p>\n\n<p>Pilih rasio berdasarkan nuansa sekaligus tujuan. Lanskap yang dipotong menjadi kotak kehilangan rasa ruangnya, sedangkan potret yang dipotong lebar kehilangan rasa kedekatannya.</p>\n\n<p>Rasio lebar membuat pemandangan terasa luas dan bebas, karena mata bergerak dari kiri ke kanan mengikuti garis horizon. Rasa lapang inilah yang membuat foto pantai dan pegunungan begitu memikat.</p>\n\n<p>Rasio tinggi membuat subjek terasa dekat dan personal, karena mata bergerak dari atas ke bawah mengikuti sosok. Rasa dekat inilah yang membuat potret vertikal terasa intim dan hangat.</p>\n\n<p>Rasio kotak terasa netral dan seimbang, karena tidak ada arah yang menonjol. Netralitas ini membuat kotak cocok untuk katalog produk, ketika perhatian harus tertuju pada barang, bukan pada bentuk bingkai.</p>\n\n<p>Cobalah memotong foto yang sama ke tiga rasio berbeda dan bandingkan rasanya. Latihan sederhana ini melatih mata Anda mengenali bagaimana bentuk mengubah cerita yang disampaikan foto.</p>\n\n<p>Untuk foto jalanan, rasio lebar menangkap suasana kota dengan lebih baik, karena jalan dan bangunan membentang secara horizontal. Rasio kotak pada foto yang sama akan memotong konteks yang membuat foto itu hidup.</p>\n\n<p>Untuk foto makanan, rasio kotak atau 4:5 sering bekerja paling baik, karena piring dan hidangan mengisi bingkai dengan padat. Rasio lebar pada foto makanan justru menyisakan ruang kosong yang tidak perlu.</p>\n\n<p>Perhatikan juga tempat foto akan dilihat. Foto untuk feed ponsel lebih cocok vertikal, sedangkan foto untuk layar televisi atau proyektor lebih cocok lebar dan sinematik.</p>\n\n<p>Pada akhirnya, rasio adalah pilihan kreatif sekaligus teknis. Bentuk yang tepat memperkuat pesan foto, sedangkan bentuk yang salah melemahkan foto yang sebenarnya bagus.</p>\n\n<h2 id=\"ratio-changes-over-time\">Rasio Berubah: Mengikuti Platform</h2>\n\n<p>Aturan ukuran platform berubah secara teratur, dan rasio yang berhasil tahun lalu mungkin tidak cocok tahun ini. Feed yang dulu menginginkan kotak mungkin kini lebih menyukai potret vertikal, dan slot spanduk mungkin memiliki ukuran baru.</p>\n\n<p>Simpan file asli untuk setiap foto penting. Saat platform mengubah aturannya, Anda bisa memotong ulang file asli ke rasio baru, bukan meregangkan potongan lama.</p>\n\n<p>Periksa panduan ukuran setiap platform sebelum memotong untuknya. Pemeriksaan dua menit mencegah potongan yang akan dipotong ulang oleh platform, dengan buruk.</p>\n\n<p>Buat daftar singkat rasio yang paling sering Anda pakai, dan perbarui saat platform berubah. Catatan di meja Anda yang bertuliskan profil 1:1, spanduk 16:9, story 9:16 menghemat waktu pada setiap sesi pemotongan.</p>\n\n<p>Gunakan 4:5 untuk postingan potret yang perlu menonjol di feed ponsel, dan 9:16 untuk story layar penuh dan video vertikal. Untuk langkah praktisnya, lihat <a href=\"/id/blog/cara-memotong-gambar/\">Cara Memotong Gambar</a> dan gambaran menyeluruh di <a href=\"/id/blog/panduan-memotong-gambar-online/\">Panduan Lengkap Memotong Gambar Online</a>. Jika foto juga perlu diubah ukurannya, gunakan <a href=\"/id/ubah-ukuran-gambar/\">Tool Ubah Ukuran Gambar</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Apa arti 1:1 dalam memotong gambar?","answer":"Artinya lebar dan tinggi sama, sehingga potongan menjadi kotak sempurna. Potongan 1:1 cocok untuk foto profil dan postingan grid. Jaga subjek tetap di tengah dengan ruang di atas kepala, karena banyak platform menampilkan kotak sebagai lingkaran dan memotong sudutnya."},{"question":"Rasio apa yang harus dipakai untuk thumbnail YouTube?","answer":"Gunakan 16:9, bentuk layar lebar standar, yang cocok dengan ukuran thumbnail 1280 kali 720 piksel. Jaga subjek utama dan teks apa pun di tengah, karena tepinya bisa terpotong di layar kecil."},{"question":"Bisakah saya memotong foto ke rasio yang tidak dipakai kamera saya?","answer":"Bisa. Memotong ke rasio baru hanya menghapus piksel dari tepi sampai bentuknya cocok. Foto lebar bisa menjadi kotak, dan kotak bisa menjadi spanduk lebar, selama area yang disimpan cukup besar untuk tujuannya."},{"question":"Rasio apa yang harus dipakai untuk mencetak foto?","answer":"Cocokkan dengan ukuran kertas: 3:2 untuk cetakan 6 kali 4 inci, 5:4 untuk cetakan 10 kali 8 inci, dan kira-kira 1,41:1 untuk A4. Periksa rasio sekaligus jumlah piksel, karena potongan kecil yang dicetak besar akan terlihat lembut."},{"question":"Mengapa Instagram memotong foto saya setelah diunggah?","answer":"Instagram memotong ulang gambar yang tidak cocok dengan rasio yang disukainya untuk slot yang Anda pilih. Memotong ke rasio yang tepat sebelum mengunggah, misalnya 1:1 untuk postingan grid atau 4:5 untuk postingan potret, menjaga bingkai tetap di bawah kendali Anda."},{"question":"Apa perbedaan rasio aspek dan resolusi?","answer":"Rasio aspek adalah bentuk gambar, misalnya 16:9, sedangkan resolusi adalah ukuran dalam piksel, misalnya 1920 kali 1080. Dua gambar bisa berbagi rasio dengan resolusi berbeda. Selalu periksa keduanya sebelum mengunggah atau mencetak."}];
